/// Gets the fully qualified name of the surrogate type that a user-declared formatter converts to and from,
/// or <see langword="null"/> when the formatter serializes the members of the data type directly.
/// </summary>
public string? SurrogateTypeName { get; init; }

/// <summary>
/// Gets the <c>Serialize</c> and <c>Deserialize</c> methods of a formatter that copies the data type into a new
/// <see cref="SurrogateTypeName"/> instance (and back) and delegates to the surrogate's own formatter.
/// </summary>
/// <returns>The C# source of both methods, without a trailing line break.</returns>
public string GetSurrogateConversionCode()
{
    string dataType = this.DataType.GetQualifiedName(Qualifiers.GlobalNamespace, GenericParameterStyle.Identifiers);
    string surrogate = this.SurrogateTypeName ?? throw new InvalidOperationException("No surrogate type.");
    string surrogateFormatter = $"global::MessagePack.FormatterResolverExtensions.GetFormatterWithVerify<{surrogate}>(options.Resolver)";
    StringBuilder builder = new();

    builder.Append($"\t\tpublic void Serialize(ref global::MessagePack.MessagePackWriter writer, {dataType} value, global::MessagePack.MessagePackSerializerOptions options)\r\n");
    builder.Append("\t\t{\r\n");
    if (this.IsClass)
    {
        builder.Append("\t\t\tif (value is null)\r\n\t\t\t{\r\n\t\t\t\twriter.WriteNil();\r\n\t\t\t\treturn;\r\n\t\t\t}\r\n\r\n");
    }

    if (this.HasIMessagePackSerializationCallbackReceiver)
    {
        builder.Append(this.NeedsCastOnBefore
            ? "\t\t\t((global::MessagePack.IMessagePackSerializationCallbackReceiver)value).OnBeforeSerialize();\r\n"
            : "\t\t\tvalue.OnBeforeSerialize();\r\n");
    }

    builder.Append($"\t\t\tvar ____surrogate = new {surrogate}()\r\n\t\t\t{{\r\n");
    foreach (MemberSerializationInfo member in this.Members)
    {
        builder.Append($"\t\t\t\t{member.Name} = value.{member.Name},\r\n");
    }

    builder.Append("\t\t\t};\r\n");
    builder.Append($"\t\t\t{surrogateFormatter}.Serialize(ref writer, ____surrogate, options);\r\n");
    builder.Append("\t\t}\r\n\r\n");

    builder.Append($"\t\tpublic {dataType} Deserialize(ref global::MessagePack.MessagePackReader reader, global::MessagePack.MessagePackSerializerOptions options)\r\n");
    builder.Append("\t\t{\r\n\t\t\tif (reader.TryReadNil())\r\n\t\t\t{\r\n");
    builder.Append(this.IsClass
        ? "\t\t\t\treturn null;\r\n"
        : "\t\t\t\tthrow new global::System.InvalidOperationException(\"typecode is null, struct not supported\");\r\n");
    builder.Append("\t\t\t}\r\n\r\n");
    builder.Append($"\t\t\tvar ____surrogate = {surrogateFormatter}.Deserialize(ref reader, options);\r\n");
    builder.Append($"\t\t\tvar ____result = new {dataType}()\r\n\t\t\t{{\r\n");
    foreach (MemberSerializationInfo member in this.Members)
    {
        builder.Append($"\t\t\t\t{member.Name} = ____surrogate.{member.Name},\r\n");
    }

    builder.Append("\t\t\t};\r\n");
    if (this.HasIMessagePackSerializationCallbackReceiver)
    {
        builder.Append(this.NeedsCastOnAfter
            ? "\t\t\t((global::MessagePack.IMessagePackSerializationCallbackReceiver)____result).OnAfterDeserialize();\r\n"
            : "\t\t\t____result.OnAfterDeserialize();\r\n");
    }

    builder.Append("\t\t\treturn ____result;\r\n\t\t}");
    return builder.ToString();
}

