/// <summary>
/// Describes the wire contract of <see cref="ExternalWidget"/>. The generated formatter converts each widget to this type and serializes it with this type's own formatter.
/// </summary>
[MessagePackObject]
public class ExternalWidgetSurrogate

[Fact]
public void SurrogateFormatterConvertsThroughSurrogate()
{
    var widget = new ExternalWidget { Id = 2, Name = "two", Internal = 5 };

    byte[] bytes = MessagePackSerializer.Serialize(widget, Options);

    // The formatter copies the widget into the surrogate and serializes it with the surrogate's own formatter.
    Assert.Equal(MessagePackSerializer.Serialize(new ExternalWidgetSurrogate { Id = 2, Name = "two" }, Options), bytes);
    ExternalWidgetSurrogate surrogate = MessagePackSerializer.Deserialize<ExternalWidgetSurrogate>(bytes, Options);
    Assert.Equal(2, surrogate.Id);
    Assert.Equal("two", surrogate.Name);
}

